text,n = re.subn(r'const ideas = \[.*?\];\nconst stages', lambda _: 'const ideas = '+new_ideas+';\nconst stages',text,count=1,flags=re.S)
if n!=1:
    raise RuntimeError('Could not find the existing ideas list')
generator.write_text(text,encoding='utf-8')
runpy.run_path(str(generator),run_name='__main__')
print(f'Wrote {len(data)} proposals, master document and updated existing canvas.')
